package com.crm.branch.controller;
import com.crm.branch.entity.Branch; import com.crm.branch.repository.BranchRepository; import com.crm.common.response.ApiResponse; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/branches") @RequiredArgsConstructor public class BranchController { private final BranchRepository repo;
@GetMapping public ApiResponse<List<Branch>> all(@RequestParam(required=false) Long companyId){List<Branch> d=companyId==null?repo.findAll():repo.findByCompanyId(companyId); return ApiResponse.<List<Branch>>builder().success(true).message("Branches fetched").data(d).build();}
@GetMapping("/{id}") public ApiResponse<Branch> get(@PathVariable Long id){return ApiResponse.<Branch>builder().success(true).message("Branch fetched").data(repo.findById(id).orElseThrow(()->new IllegalArgumentException("Branch not found"))).build();}
@PostMapping @ResponseStatus(HttpStatus.CREATED) public ApiResponse<Branch> create(@Valid @RequestBody Branch b){if(repo.existsByCode(b.getCode())) throw new IllegalArgumentException("Branch code already exists"); return ApiResponse.<Branch>builder().success(true).message("Branch created").data(repo.save(b)).build();}
@PutMapping("/{id}") public ApiResponse<Branch> update(@PathVariable Long id,@Valid @RequestBody Branch b){Branch x=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Branch not found")); x.setName(b.getName());x.setCode(b.getCode());x.setCompanyId(b.getCompanyId());x.setAddress(b.getAddress());x.setPhone(b.getPhone());x.setActive(b.isActive());return ApiResponse.<Branch>builder().success(true).message("Branch updated").data(repo.save(x)).build();}
@DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable Long id){repo.deleteById(id);return ApiResponse.<Void>builder().success(true).message("Branch deleted").build();}}